={
  "success": true,
  "message": "Sự kiện đã được n8n Alert Hub tiếp nhận và chuyển tiếp an toàn!",
  "timestamp": "{{ $now.toISO() }}"
}

parameters.jsCode:
// 1. Lấy dữ liệu payload từ Webhook
const body = $input.first().json.body || $input.first().json;

const eventType = body.eventType || body.type || 'generic';
const botToken = (body.botToken || '').trim();
const chatId = (body.chatId || body.telegramGroupChatId || body.telegramChatId || '').trim();
const data = body.data || body;
const rawMsg = body.message || '';

if (!botToken || !chatId) {
  // Không có bot token hoặc chat ID của admin này -> Bỏ qua an toàn, không gửi nhầm
  return [];
}

const nowStr = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

function formatCurrency(val) {
  const n = Number(String(val || 0).replace(/[^0-9.-]/g, '')) || 0;
  return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(n);
}

let formattedText = '';

if (rawMsg && !data.customFormat) {
  formattedText = rawMsg;
} else if (eventType === 'attendance') {
  const actionStr = data.action === 'checkout' ? '🚪 RA CA (CHECK-OUT)' : '🏢 VÀO CA (CHECK-IN)';
  const icon = data.action === 'checkout' ? '👋' : '⏰';
  formattedText = `${icon} <b>THÔNG BÁO CHẤM CÔNG - ${actionStr}</b>\n\n` +
    `👤 <b>Nhân viên:</b> <b>${data.userName || 'Nhân viên'}</b>\n` +
    `📧 <b>Email:</b> <code>${data.userEmail || '---'}</code>\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}\n` +
    (data.distance != null ? `📏 <b>Khoảng cách tới xưởng:</b> <b>${data.distance} mét</b> ${data.distance > 200 ? '⚠️ (Ngoài bán kính chuẩn)' : '✅'}\n` : '') +
    (data.location ? `📍 <b>Tọa độ:</b> <code>${data.location.lat?.toFixed(5)}, ${data.location.lng?.toFixed(5)}</code>\n` : '') +
    (data.status ? `📊 <b>Trạng thái:</b> ${data.status === 'Đúng giờ' ? '🟢 Đúng giờ' : '🟡 ' + data.status}\n` : '') +
    `⚡ <i>Ghi nhận tự động từ ứng dụng Dunvex Build.</i>`;
} else if (eventType === 'site_checkin') {
  formattedText = `📍 <b>CHECK-IN TẠI CÔNG TRÌNH / GIAO HÀNG</b>\n\n` +
    `👤 <b>Nhân viên:</b> <b>${data.userName || 'Nhân viên'}</b>\n` +
    `🏗️ <b>Khách hàng / Công trình:</b> <b>${data.customerName || data.siteName || 'Công trình'}</b>\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}\n` +
    (data.distance != null ? `📏 <b>Khoảng cách:</b> <b>${data.distance} mét</b>\n` : '') +
    (data.location ? `🗺️ <b>Vị trí GPS:</b> <a href="https://www.google.com/maps/search/?api=1&query=${data.location.lat},${data.location.lng}">Xem bản đồ vệ tinh</a>\n` : '') +
    (data.imageUrl ? `📸 <b>Ảnh hiện trường:</b> <a href="${data.imageUrl}">Xem ảnh chụp tại chỗ</a>\n` : '') +
    (data.note ? `📝 <b>Ghi chú:</b> <i>${data.note}</i>\n` : '') +
    `🚚 <i>Được định vị chính xác qua GPS di động.</i>`;
} else if (eventType === 'debt_payment') {
  formattedText = `💰 <b>GHI NHẬN THU NỢ KHÁCH HÀNG</b>\n\n` +
    `👤 <b>Khách hàng:</b> <b>${data.customerName || 'Khách hàng'}</b>\n` +
    `💵 <b>Số tiền thu:</b> <b>${formatCurrency(data.amount)}</b>\n` +
    `💳 <b>Hình thức:</b> ${data.paymentMethod || 'Tiền mặt / Chuyển khoản'}\n` +
    (data.remainingDebt != null ? `📉 <b>Dư nợ sau khi thu:</b> <b>${formatCurrency(data.remainingDebt)}</b>\n` : '') +
    `👨‍💼 <b>Người thu:</b> ${data.collectorName || data.user || 'Nhân viên'}\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}\n` +
    (data.note ? `📝 <b>Nội dung:</b> <i>${data.note}</i>\n` : '') +
    `📑 <i>Phiếu thu đã được ghi sổ tự động và đối soát vào CSDL.</i>`;
} else if (eventType === 'leave_request') {
  const reqType = data.requestType === 'leave' ? '🏖️ NGHỈ PHÉP' : '⏰ XIN ĐI MUỘN';
  formattedText = `📝 <b>ĐƠN ĐĂNG KÝ ${reqType}</b>\n\n` +
    `👤 <b>Nhân viên:</b> <b>${data.userName || 'Nhân viên'}</b>\n` +
    `📧 <b>Email:</b> <code>${data.userEmail || '---'}</code>\n` +
    `📅 <b>Ngày đăng ký:</b> <b>${Array.isArray(data.dates) ? data.dates.join(', ') : (data.dates || data.date || 'Hôm nay')}</b>\n` +
    `💬 <b>Lý do:</b> <i>${data.note || data.reason || 'Bận việc gia đình'}</i>\n` +
    `🕒 <b>Thời gian gửi:</b> ${data.time || nowStr}\n` +
    `🔔 <i>Vui lòng vào mục Quản lý nghỉ phép để xét duyệt cho nhân viên.</i>`;
} else if (eventType === 'order') {
  formattedText = `🛒 <b>CẬP NHẬT ĐƠN HÀNG DUNVEX</b>\n\n` +
    `👤 <b>Khách hàng:</b> <b>${data.customerName || 'Khách hàng'}</b>\n` +
    `💰 <b>Tổng tiền:</b> <b>${formatCurrency(data.totalAmount || data.amount)}</b>\n` +
    `📦 <b>Trạng thái:</b> <b>${data.status || 'Đơn chốt'}</b>\n` +
    `👨‍💼 <b>Thao tác bởi:</b> ${data.actorName || data.user || 'Admin'}\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}`;
} else {
  formattedText = `🔔 <b>THÔNG BÁO HỆ THỐNG DUNVEX</b>\n\n${rawMsg || JSON.stringify(data)}`;
}

return [{
  json: {
    botToken,
    chatId,
    text: formattedText,
    eventType
  }
}];

